mapper.update:
update application_automation_reference_replicas
set status = 'PENDING', retry_count = 0, next_retry_at = null,
    lease_token = null, lease_until = null, last_error = null, updated_at = #{now}
where app_id = #{appId} and repository_id = #{repositoryId} and generation = #{generation}
  and linux_server_id = #{linuxServerId}

update application_automation_reference_replicas
set status = 'DEFERRED', lease_token = null, lease_until = null, updated_at = #{now}
where app_id = #{appId} and repository_id = #{repositoryId} and generation = #{generation}
  and status in ('PENDING', 'RETRY_WAIT', 'PROCESSING')

  and linux_server_id not in

      #{serverId}

update application_automation_reference_replicas
set status = 'PROCESSING', lease_token = #{leaseToken}, lease_until = #{leaseUntil}, updated_at = #{now}
where app_id = #{appId} and repository_id = #{repositoryId} and generation = #{generation}
  and linux_server_id = #{linuxServerId}
  and (
    status in ('PENDING', 'DEFERRED')
    or (status = 'RETRY_WAIT' and (next_retry_at is null or next_retry_at <= #{now}))
    or (status = 'PROCESSING' and lease_until <= #{now})
  )
  and exists (
    select 1 from application_automation_references state
    where state.app_id = #{appId} and state.repository_id = #{repositoryId}
      and state.status in ('INITIALIZING', 'VERIFYING', 'SYNCHRONIZING', 'READY')
      and (state.pending_generation = #{generation} or state.active_generation = #{generation})
  )

update application_automation_reference_replicas
set lease_until = #{leaseUntil}, updated_at = #{now}
where app_id = #{appId} and repository_id = #{repositoryId} and generation = #{generation}
  and linux_server_id = #{linuxServerId} and status = 'PROCESSING'
  and lease_token = #{leaseToken} and lease_until > #{now}

update application_automation_reference_replicas
set status = 'READY', current_branch = #{branch}, current_commit_hash = #{commitHash},
    retry_count = 0, next_retry_at = null, lease_token = null, lease_until = null,
    last_error = null, synced_at = #{syncedAt}, updated_at = #{now}
where app_id = #{appId} and repository_id = #{repositoryId} and generation = #{generation}
  and linux_server_id = #{linuxServerId} and status = 'PROCESSING'
  and lease_token = #{leaseToken} and lease_until > #{now}

update application_automation_reference_replicas
set status = 'RETRY_WAIT', retry_count = #{retryCount}, next_retry_at = #{nextRetryAt},
    lease_token = null, lease_until = null, last_error = #{lastError}, updated_at = #{now}
where app_id = #{appId} and repository_id = #{repositoryId} and generation = #{generation}
  and linux_server_id = #{linuxServerId} and status = 'PROCESSING'
  and lease_token = #{leaseToken} and lease_until > #{now}

update application_automation_reference_replicas
set status = 'BLOCKED', next_retry_at = null, lease_token = null, lease_until = null,
    last_error = #{lastError}, updated_at = #{now}
where app_id = #{appId} and repository_id = #{repositoryId} and generation = #{generation}
  and linux_server_id = #{linuxServerId} and status = 'PROCESSING'
  and lease_token = #{leaseToken} and lease_until > #{now}

update application_automation_reference_replicas
set status = #{status}, current_branch = #{actualBranch}, current_commit_hash = #{actualCommitHash},
    retry_count = 0, next_retry_at = null, lease_token = null, lease_until = null,
    last_error = #{lastError}, verified_at = #{verifiedAt}, updated_at = #{now}
where app_id = #{appId} and repository_id = #{repositoryId} and generation = #{generation}
  and linux_server_id = #{linuxServerId} and status = 'PROCESSING'
  and lease_token = #{leaseToken} and lease_until > #{now}

update application_automation_reference_generations
set status = #{status}, last_error = #{lastError},
    activated_at = case when #{status} = 'READY' and activated_at is null then #{activatedAt} else activated_at end,
    updated_at = #{now}
where app_id = #{appId} and repository_id = #{repositoryId} and generation = #{generation}
  and status in ('SYNCHRONIZING', 'READY')

update application_automation_references
set active_generation = case
        when #{status} = 'READY' and pending_generation = #{generation} then #{generation}
        else active_generation end,
    pending_generation = case when pending_generation = #{generation} then null else pending_generation end,
    lock_version = lock_version + 1,
    status = #{status},
    last_error = #{lastError},
    updated_at = #{now}
where app_id = #{appId} and repository_id = #{repositoryId}
  and status in ('INITIALIZING', 'VERIFYING', 'SYNCHRONIZING')
  and (pending_generation = #{generation} or active_generation = #{generation})

update application_automation_references
set pending_generation = case when pending_generation = #{generation} then null else pending_generation end,
    lock_version = lock_version + 1,
    status = 'FAILED', last_error = #{lastError}, updated_at = #{now}
where app_id = #{appId} and repository_id = #{repositoryId}
  and lock_version = #{expectedLockVersion}
  and status in ('INITIALIZING', 'VERIFYING', 'SYNCHRONIZING')
  and (pending_generation = #{generation} or active_generation = #{generation})

update application_automation_reference_generations
set status = 'FAILED', last_error = #{lastError}, updated_at = #{now}
where app_id = #{appId} and repository_id = #{repositoryId} and generation = #{generation}
  and status = 'SYNCHRONIZING'

update application_automation_reference_replicas
set status = 'BLOCKED', next_retry_at = null, lease_token = null, lease_until = null,
    last_error = #{lastError}, updated_at = #{now}
where app_id = #{appId} and repository_id = #{repositoryId} and generation = #{generation}
  and status in ('PENDING', 'PROCESSING', 'RETRY_WAIT', 'DEFERRED')

