    #{runId}, #{appId}, #{repositoryId}, #{generation}, #{linuxServerId}, #{now}
)

insert into application_automation_reference_read_leases(
    token_hash, user_id, workspace_id, app_id, repository_id, generation,
    expires_at, created_at, updated_at
)
select #{tokenHash}, #{userId}, #{workspaceId}, generation_row.app_id,
       generation_row.repository_id, generation_row.generation, #{expiresAt}, #{now}, #{now}
from application_automation_reference_generations generation_row
join application_automation_references state
  on state.app_id = generation_row.app_id and state.repository_id = generation_row.repository_id
where generation_row.app_id = #{appId}
  and generation_row.repository_id = #{repositoryId}
  and generation_row.generation = #{generation}
  and generation_row.status = 'READY'
  and state.active_generation = generation_row.generation

mapper.update:
update application_automation_reference_read_leases
set expires_at = #{nextExpiresAt}, updated_at = #{now}
where token_hash = #{tokenHash}
  and user_id = #{userId}
  and workspace_id = #{workspaceId}
  and app_id = #{appId}
  and repository_id = #{repositoryId}
  and generation = #{generation}
  and expires_at > #{now}

update application_automation_reference_generations generation_row
set status = 'RETIRED', updated_at = #{now}
where generation_row.app_id = #{appId}
  and generation_row.repository_id = #{repositoryId}
  and generation_row.generation = #{generation}
  and generation_row.status = 'READY'
  and not exists (
      select 1 from application_automation_references state
      where state.app_id = generation_row.app_id
        and state.repository_id = generation_row.repository_id
        and (state.active_generation = generation_row.generation
             or state.pending_generation = generation_row.generation)
  )
  and not exists (
      select 1 from application_automation_reference_run_leases run_lease
      where run_lease.app_id = generation_row.app_id
        and run_lease.repository_id = generation_row.repository_id
        and run_lease.generation = generation_row.generation
  )
  and not exists (
      select 1 from application_automation_reference_read_leases read_lease
      where read_lease.app_id = generation_row.app_id
        and read_lease.repository_id = generation_row.repository_id
        and read_lease.generation = generation_row.generation
        and read_lease.expires_at > #{now}
  )

mapper.delete:
delete from application_automation_reference_replicas replica
where replica.app_id = #{appId}
  and replica.repository_id = #{repositoryId}
  and replica.generation = #{generation}
  and replica.linux_server_id = #{linuxServerId}
  and exists (
      select 1 from application_automation_reference_generations generation_row
      where generation_row.app_id = replica.app_id
        and generation_row.repository_id = replica.repository_id
        and generation_row.generation = replica.generation
        and generation_row.status = 'RETIRED'
  )
